action.code:
float r1 = 2 * u[0] - 1;
float r2 = 2 * u[1] - 1;
if (r1 == 0 && r2 == 0) return Point2f(0, 0);
float theta, r;
if (std::abs(r1) > std::abs(r2)) {
    r = r1;
    theta = (M_PI / 4) * (r2 / r1);
} else {
    r = r2;
    theta = (M_PI / 2) - (M_PI / 4) * (r1 / r2);
}
return r * Point2f(std::cos(theta), std::sin(theta));

